// Copies the browser-ready libraries FieldLogger uses into src/vendor so the
// renderer can load them as plain ES modules (no bundler needed).
//   npm run vendor
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const nm = path.join(root, 'node_modules');
const out = path.join(root, 'src', 'vendor');
fs.mkdirSync(path.join(out, 'fonts'), { recursive: true });

const read = (p) => fs.readFileSync(path.join(nm, p), 'utf8');
const write = (name, text) => fs.writeFileSync(path.join(out, name), text);
const stripMap = (s) => s.replace(/\/\/# sourceMappingURL=.*$/m, '');

// Preact + hooks + htm (hooks imports the bare "preact" specifier, so point it at our copy)
write('preact.mjs', stripMap(read('preact/dist/preact.mjs')));
write('hooks.mjs', stripMap(read('preact/hooks/dist/hooks.mjs')).replace(/from\s*"preact"/g, 'from"./preact.mjs"'));
write('htm.mjs', stripMap(read('htm/dist/htm.mjs')));

// Fonts
fs.copyFileSync(path.join(nm, '@fontsource-variable/inter/files/inter-latin-wght-normal.woff2'), path.join(out, 'fonts', 'inter.woff2'));
fs.copyFileSync(path.join(nm, '@fontsource-variable/outfit/files/outfit-latin-wght-normal.woff2'), path.join(out, 'fonts', 'outfit.woff2'));

// Icons (Lucide, ISC license) - only the ones the app uses
const ICONS = `
phone phone-call mail mail-check database layout-template key-round graduation-cap handshake rocket settings-2
users file-text presentation message-square video wrench clipboard-check calendar calendar-days calendar-range
calendar-check building-2 notebook-pen settings sun moon monitor plus search chevron-left chevron-right
chevron-down chevron-up x copy check clock timer play square trash-2 pencil star user user-plus user-round
ellipsis log-out lock lock-open download upload folder-open palette list layout-grid sparkles filter archive
archive-restore eye eye-off circle-check copy-check arrow-right arrow-left history zap panel-left keyboard info
triangle-alert briefcase hard-hat map-pin flag headset server table sheet lightbulb target bookmark link at-sign
building circle-dot grip-vertical arrow-up arrow-down rotate-ccw undo-2 square-pen clipboard-list hourglass
chart-column house layout-dashboard list-checks shield-check refresh-cw send file-spreadsheet cloud-upload truck
hammer construction monitor-play circle-help sticky-note external-link circle minus contrast droplet type gauge
globe repeat arrow-up-right clipboard-paste square-check square-dashed circle-pause mouse-pointer-click
calendar-plus list-todo inbox wand-sparkles party-popper badge-check map ruler drafting-compass shovel
`.trim().split(/\s+/);

const icons = {};
const missing = [];
for (const name of ICONS) {
  const file = path.join(nm, 'lucide-static', 'icons', `${name}.svg`);
  if (!fs.existsSync(file)) { missing.push(name); continue; }
  const svg = fs.readFileSync(file, 'utf8');
  const inner = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'));
  icons[name] = inner.replace(/\s*\n\s*/g, '').trim();
}
write('icons.js', `// Generated by scripts/vendor.js from lucide-static (ISC license). Do not edit.\nexport const ICONS = ${JSON.stringify(icons, null, 0).replace(/","/g, '",\n"')};\n`);

console.log(`Vendored preact, hooks, htm, 2 fonts and ${Object.keys(icons).length} icons.`);
if (missing.length) console.log('Missing icons:', missing.join(', '));
